<?phpnamespace app\common\model;use Endroid\QrCode\QrCode as CodeMode;use Endroid\QrCode\Writer\PngWriter;/** * 聚合二维码模型 */class Qrcode extends BaseModel{    // 定义表名    protected $name = 'qrcode';        // 定义主键    protected $pk = 'qrcode_id';        // 追加字段    protected $append = ['qrcode'];        /**     * 二维码     */    public function getQrcodeAttr($value,$data)    {        $file_path = 'temp/sn-' . $data['qrcode_id'] . '.png';        if(!is_file('./'.$file_path)){            if(!file_exists('./temp')){                mkdir('./temp',0777,true);            }            $writer = new PngWriter();            $qrCode = CodeMode::create(base_url() . 'api/h5/index/scene/sn-' . $data['qrcode_id'])                ->setSize(500);            $result = $writer->write($qrCode);            $result->saveToFile('./' . $file_path);        }        return base_url() . $file_path;    }    /**     * 关联餐桌表     */    public function table()    {        return $this->belongsTo('app\\common\\model\\Table','table_id');    }        /**     * 二维码类型     */    public function getTypeAttr($value)    {        $status = [10 => '小程序码', 20 => '门店码', 30 => '餐桌码', 40 => 'WIFI码', 50 => '买单码', 60 => '自定义'];        return ['text' => $status[$value], 'value' => $value];    }    /**     * 获取列表     */    public function getList()    {        //筛选条件        $filter = [];        // 执行查询        return $this->with(['table'])            ->where($filter)            ->order(['qrcode_id' => 'desc'])            ->paginate(['list_rows'=>15,'query' => request()->param()]);    }        /**     * 获取详情     */    public static function detail($id)    {        return self::with(['table'])->find($id);    }    /**     * 添加     */    public function add($data)    {        $qrcode = array();        for($n=0;$n<$data['count'];$n++){            $qrcode[] = [                'type' => 10            ];        }        return $this->saveAll($qrcode);    }    /**     * 编辑     */    public function edit(array $data)    {        if($data['type'] != 30){           $data['table_id'] = 0;        }else{            if($data['table_id'] == 0){               $this->error = '请选择要关联的餐桌';               return false;            }        }        if($data['type'] != 60){           $data['url'] = '';        }else{            if($data['url'] == ''){               $this->error = '请输入跳转位置';               return false;            }        }        return $this->save($data) !== false;    }    /**     * 删除     */    public function remove()    {        @unlink('./temp/sn-' . $this->qrcode_id . '.png');        return $this->delete();    }    }